<script>
(()=>{const button=document.getElementById('aiDraftButton'),field=document.getElementById('rfqRequirements'),status=document.getElementById('rfqAiStatus'),count=document.getElementById('rfqCharCount');if(!button||!field)return;field.addEventListener('input',()=>count.textContent=field.value.length+'/8000');button.addEventListener('click',async()=>{const product=document.querySelector('[name="product_name"]')?.value.trim();if(!product){status.textContent='Enter the product name first.';document.querySelector('[name="product_name"]')?.focus();return;}button.disabled=true;button.textContent='Writing…';status.textContent='';try{const response=await fetch(@json(route('customer.rfqs.draft')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({product_name:product,notes:field.value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Could not draft this request.');field.value=data.draft;field.dispatchEvent(new Event('input',{bubbles:true}));status.style.color='#197047';status.textContent='Draft ready. Please review and edit it before posting.';}catch(error){status.style.color='#b42318';status.textContent=error.message;}finally{button.disabled=false;button.textContent='✦ Write with AI';}});})();
</script>
